package br.edu.ifms.robotica.servlet;
import java.io.IOException;import java.sql.SQLException;import javax.servlet.*;import javax.servlet.annotation.*;import javax.servlet.http.*;import br.edu.ifms.robotica.dao.EstudanteDAO;import br.edu.ifms.robotica.model.Estudante;import br.edu.ifms.robotica.seguranca.SenhaUtil;import br.edu.ifms.robotica.util.UploadUtil;
@WebServlet("/admin/estudantes") @MultipartConfig(maxFileSize=5242880)
public class EstudanteServlet extends HttpServlet{private final EstudanteDAO dao=new EstudanteDAO();
 @Override protected void doGet(HttpServletRequest r,HttpServletResponse p)throws ServletException,IOException{try{r.setAttribute("estudantes",dao.listar());r.getRequestDispatcher("/WEB-INF/views/admin/estudantes.jsp").forward(r,p);}catch(SQLException e){throw new ServletException(e);}}
 @Override protected void doPost(HttpServletRequest r,HttpServletResponse p)throws ServletException,IOException{r.setCharacterEncoding("UTF-8");String a=r.getParameter("acao");try{if("inativar".equals(a)||"reativar".equals(a)){dao.alterarAtivo(id(r),"reativar".equals(a));redirecionar(r,p,a);return;}Estudante e=new Estudante();if("editar".equals(a))e.setId(id(r));e.setNome(obrigatorio(r,"nome"));e.setMinibio(r.getParameter("minibio"));e.setEmail(obrigatorio(r,"email"));if(dao.emailEmUso(e.getEmail(),e.getId())){erro(r,p,"erro.email.duplicado");return;}e.setFoto(UploadUtil.salvar(r.getPart("foto"),"estudantes",e.getNome()));if("editar".equals(a))dao.atualizar(e);else{e.setSenhaHash(SenhaUtil.gerarHash(r.getParameter("senha")));dao.inserir(e);}redirecionar(r,p,"editar".equals(a)?"alteracao":"cadastro");}catch(IllegalArgumentException e){erro(r,p,e.getMessage());}catch(SQLException e){throw new ServletException("Erro ao processar estudante.",e);}}
 private Long id(HttpServletRequest r){return Long.valueOf(r.getParameter("id"));}private String obrigatorio(HttpServletRequest r,String n){String v=r.getParameter(n);if(v==null||v.isBlank())throw new IllegalArgumentException("erro.campo.obrigatorio");return v.trim();}private void erro(HttpServletRequest r,HttpServletResponse p,String e)throws ServletException,IOException{r.setAttribute("erro",e);doGet(r,p);}private void redirecionar(HttpServletRequest r,HttpServletResponse p,String s)throws IOException{p.sendRedirect(r.getContextPath()+"/admin/estudantes?sucesso="+s);}}
